[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

    :root {
      --navy: #1B1464;
      --navy-light: #2a2080;
      --yellow: #FFD930;
      --yellow-hover: #ffe566;
      --white: #FFFFFF;
      --gray-50: #F9FAFB;
      --gray-100: #F3F4F6;
      --gray-200: #E5E7EB;
      --gray-300: #D1D5DB;
      --gray-500: #6B7280;
      --gray-600: #4B5563;
      --gray-700: #374151;
      --gray-800: #1F2937;
      --teal: #0EA5A0;
      --teal-light: #e6f9f8;
      --radius-sm: 8px;
      --radius-md: 12px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
      --shadow-lg: 0 8px 30px rgba(0,0,0,0.1);
      --shadow-xl: 0 12px 40px rgba(0,0,0,0.12);
      --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      color: var(--gray-800);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    /* ===== HEADER ===== */
    .header {
      position: fixed;
      top: 0; left: 0; right: 0;
      z-index: 1000;
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
      transition: box-shadow var(--transition);
    }
    .header.scrolled { box-shadow: var(--shadow-md); }

    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      height: 64px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 10px;
      text-decoration: none;
      font-weight: 800;
      font-size: 22px;
      color: var(--navy);
    }
    .logo-icon {
      width: 36px; height: 36px;
      background: var(--navy);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .logo-icon svg { width: 22px; height: 22px; }
    .logo span { color: var(--yellow); }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 8px;
      list-style: none;
    }
    .nav-links a {
      text-decoration: none;
      color: var(--gray-700);
      font-weight: 500;
      font-size: 14px;
      padding: 8px 16px;
      border-radius: var(--radius-sm);
      transition: all var(--transition);
    }
    .nav-links a:hover { background: var(--gray-100); color: var(--navy); }

    .btn-login {
      color: var(--navy) !important;
      font-weight: 600 !important;
    }
    .btn-signup {
      background: var(--navy) !important;
      color: var(--white) !important;
      padding: 8px 20px !important;
    }
    .btn-signup:hover { background: var(--navy-light) !important; }

    .hamburger {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
      border-radius: var(--radius-sm);
      transition: background var(--transition);
    }
    .hamburger:hover { background: var(--gray-100); }
    .hamburger svg { width: 24px; height: 24px; color: var(--navy); }

    /* Mobile drawer */
    .mobile-drawer {
      position: fixed;
      top: 0; right: -300px;
      width: 300px;
      height: 100vh;
      background: var(--white);
      z-index: 1001;
      transition: right 0.3s ease;
      box-shadow: var(--shadow-xl);
      padding: 24px;
      display: flex;
      flex-direction: column;
    }
    .mobile-drawer.open { right: 0; }

    .drawer-close {
      align-self: flex-end;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
      border-radius: var(--radius-sm);
    }
    .drawer-close:hover { background: var(--gray-100); }
    .drawer-close svg { width: 24px; height: 24px; color: var(--gray-600); }

    .drawer-links {
      list-style: none;
      margin-top: 24px;
      display: flex;
      flex-direction: column;
      gap: 4px;
    }
    .drawer-links a {
      text-decoration: none;
      color: var(--gray-700);
      font-weight: 500;
      font-size: 16px;
      padding: 12px 16px;
      border-radius: var(--radius-sm);
      display: block;
      transition: all var(--transition);
    }
    .drawer-links a:hover { background: var(--gray-100); color: var(--navy); }

    .drawer-links .btn-signup-drawer {
      margin-top: 16px;
      background: var(--navy);
      color: var(--white) !important;
      text-align: center;
      border-radius: var(--radius-sm);
    }

    .drawer-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.4);
      z-index: 1000;
      opacity: 0;
      visibility: hidden;
      transition: all 0.3s ease;
    }
    .drawer-overlay.open { opacity: 1; visibility: visible; }

    /* ===== HERO ===== */
    .hero {
      padding: 120px 24px 60px;
      background: linear-gradient(135deg, var(--navy) 0%, var(--navy-light) 60%, #3b2ea0 100%);
      position: relative;
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      top: -200px; right: -200px;
      width: 600px; height: 600px;
      background: radial-gradient(circle, rgba(255,217,48,0.12) 0%, transparent 70%);
      pointer-events: none;
    }
    .hero::after {
      content: '';
      position: absolute;
      bottom: -100px; left: -100px;
      width: 400px; height: 400px;
      background: radial-gradient(circle, rgba(14,165,160,0.1) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero-inner {
      max-width: 800px;
      margin: 0 auto;
      text-align: center;
      position: relative;
      z-index: 1;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(255,255,255,0.12);
      border: 1px solid rgba(255,255,255,0.15);
      border-radius: 100px;
      padding: 6px 16px;
      font-size: 13px;
      font-weight: 500;
      color: var(--yellow);
      margin-bottom: 24px;
      backdrop-filter: blur(8px);
    }
    .hero-badge svg { width: 16px; height: 16px; }

    .hero h1 {
      font-size: clamp(36px, 5vw, 56px);
      font-weight: 800;
      color: var(--white);
      line-height: 1.1;
      margin-bottom: 20px;
      letter-spacing: -0.02em;
    }

    .hero p {
      font-size: clamp(16px, 2vw, 19px);
      color: rgba(255,255,255,0.8);
      max-width: 600px;
      margin: 0 auto 32px;
      line-height: 1.6;
    }

    .hero-cta {
      display: inline-flex;
      align-items: center;
      gap: 12px;
    }
    .btn-primary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--yellow);
      color: var(--navy);
      font-weight: 700;
      font-size: 16px;
      padding: 14px 28px;
      border-radius: var(--radius-md);
      border: none;
      cursor: pointer;
      text-decoration: none;
      transition: all var(--transition);
      box-shadow: 0 4px 14px rgba(255,217,48,0.35);
    }
    .btn-primary:hover {
      background: var(--yellow-hover);
      transform: translateY(-1px);
      box-shadow: 0 6px 20px rgba(255,217,48,0.45);
    }
    .btn-secondary {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(255,255,255,0.12);
      color: var(--white);
      font-weight: 600;
      font-size: 16px;
      padding: 14px 28px;
      border-radius: var(--radius-md);
      border: 1px solid rgba(255,255,255,0.2);
      cursor: pointer;
      text-decoration: none;
      transition: all var(--transition);
      backdrop-filter: blur(4px);
    }
    .btn-secondary:hover {
      background: rgba(255,255,255,0.18);
      border-color: rgba(255,255,255,0.35);
    }

    /* ===== SEARCH ===== */
    .search-section {
      position: relative;
      z-index: 10;
      padding: 0 24px;
      margin-top: -40px;
      margin-bottom: 60px;
    }

    .search-card {
      max-width: 900px;
      margin: 0 auto;
      background: var(--white);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-xl);
      padding: 8px;
      position: relative;
    }

    .search-form {
      display: flex;
      align-items: stretch;
      gap: 0;
    }

    .search-field {
      flex: 1;
      position: relative;
      display: flex;
      align-items: center;
      padding: 0 16px;
    }
    .search-field svg {
      width: 20px; height: 20px;
      color: var(--gray-500);
      flex-shrink: 0;
      margin-right: 10px;
    }
    .search-field input,
    .search-field select {
      width: 100%;
      border: none;
      outline: none;
      font-family: inherit;
      font-size: 15px;
      color: var(--gray-800);
      background: transparent;
      padding: 14px 0;
    }
    .search-field input::placeholder { color: var(--gray-300); }
    .search-field select { cursor: pointer; -webkit-appearance: none; appearance: none; color: var(--gray-500); }

    .search-divider {
      width: 1px;
      background: var(--gray-200);
      align-self: stretch;
      margin: 8px 0;
    }

    .search-btn {
      background: var(--navy);
      color: var(--white);
      border: none;
      border-radius: var(--radius-md);
      padding: 14px 32px;
      font-family: inherit;
      font-weight: 700;
      font-size: 15px;
      cursor: pointer;
      transition: all var(--transition);
      white-space: nowrap;
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .search-btn:hover { background: var(--navy-light); }
    .search-btn svg { width: 18px; height: 18px; }

    /* Autocomplete dropdown */
    .autocomplete-dropdown {
      position: absolute;
      top: calc(100% + 4px);
      left: 0; right: 0;
      background: var(--white);
      border-radius: var(--radius-md);
      box-shadow: var(--shadow-lg);
      border: 1px solid var(--gray-200);
      display: none;
      z-index: 20;
      overflow: hidden;
    }
    .autocomplete-dropdown.visible { display: block; }

    .autocomplete-item {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 12px 16px;
      cursor: pointer;
      transition: background var(--transition);
      font-size: 14px;
      color: var(--gray-700);
    }
    .autocomplete-item:hover { background: var(--gray-50); }
    .autocomplete-item svg { width: 18px; height: 18px; color: var(--gray-400); flex-shrink: 0; }
    .autocomplete-item .type { color: var(--gray-400); font-size: 12px; margin-left: auto; text-transform: uppercase; letter-spacing: 0.5px; }
    .autocomplete-item mark { background: var(--yellow); color: var(--navy); border-radius: 2px; padding: 0 1px; }

    /* Geolocation button */
    .geo-btn {
      background: none;
      border: none;
      cursor: pointer;
      padding: 4px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--teal);
      transition: all var(--transition);
      flex-shrink: 0;
    }
    .geo-btn:hover { background: var(--teal-light); }
    .geo-btn svg { width: 18px; height: 18px; }

    /* ===== SPECIALTIES ===== */
    .specialties {
      padding: 60px 24px 80px;
      background: var(--gray-50);
    }

    .section-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .section-header {
      text-align: center;
      margin-bottom: 48px;
    }
    .section-header h2 {
      font-size: clamp(28px, 3.5vw, 36px);
      font-weight: 800;
      color: var(--navy);
      margin-bottom: 12px;
      letter-spacing: -0.02em;
    }
    .section-header p {
      font-size: 17px;
      color: var(--gray-500);
      max-width: 500px;
      margin: 0 auto;
    }

    .specialties-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }

    .specialty-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 28px 24px;
      text-decoration: none;
      color: inherit;
      border: 1px solid var(--gray-200);
      transition: all var(--transition);
      cursor: pointer;
      display: flex;
      align-items: flex-start;
      gap: 16px;
    }
    .specialty-card:hover {
      border-color: var(--navy);
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .specialty-icon {
      width: 52px; height: 52px;
      border-radius: var(--radius-md);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      transition: transform var(--transition);
    }
    .specialty-card:hover .specialty-icon { transform: scale(1.08); }
    .specialty-icon svg { width: 28px; height: 28px; }

    .specialty-icon.primary { background: #eef2ff; color: #4338ca; }
    .specialty-icon.dentist { background: #fef3c7; color: #b45309; }
    .specialty-icon.derma { background: #fce7f3; color: #be185d; }
    .specialty-icon.psych { background: #ede9fe; color: #7c3aed; }
    .specialty-icon.eye { background: #d1fae5; color: #047857; }
    .specialty-icon.ortho { background: #fee2e2; color: #b91c1c; }

    .specialty-info h3 {
      font-size: 16px;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 4px;
    }
    .specialty-info p {
      font-size: 14px;
      color: var(--gray-500);
      line-height: 1.5;
    }

    /* ===== HOW IT WORKS ===== */
    .how-it-works {
      padding: 80px 24px;
      background: var(--white);
    }

    .steps-container {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 40px;
      position: relative;
    }

    .steps-container::before {
      content: '';
      position: absolute;
      top: 48px;
      left: 16.67%;
      right: 16.67%;
      height: 2px;
      background: var(--gray-200);
      z-index: 0;
    }

    .step {
      text-align: center;
      position: relative;
      z-index: 1;
    }

    .step-number {
      width: 56px; height: 56px;
      border-radius: 50%;
      background: var(--navy);
      color: var(--yellow);
      font-weight: 800;
      font-size: 22px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 20px;
      box-shadow: 0 4px 14px rgba(27,20,100,0.2);
    }

    .step h3 {
      font-size: 18px;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 8px;
    }
    .step p {
      font-size: 15px;
      color: var(--gray-500);
      line-height: 1.6;
      max-width: 300px;
      margin: 0 auto;
    }

    /* ===== STATS ===== */
    .stats {
      padding: 48px 24px;
      background: var(--navy);
    }

    .stats-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .stat-item {
      text-align: center;
      padding: 20px;
    }
    .stat-value {
      font-size: clamp(28px, 3vw, 38px);
      font-weight: 800;
      color: var(--yellow);
      margin-bottom: 4px;
      letter-spacing: -0.02em;
    }
    .stat-label {
      font-size: 14px;
      color: rgba(255,255,255,0.75);
      font-weight: 500;
    }

    /* ===== TESTIMONIALS ===== */
    .testimonials {
      padding: 80px 24px;
      background: var(--gray-50);
    }

    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .testimonial-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 32px;
      border: 1px solid var(--gray-200);
      transition: all var(--transition);
    }
    .testimonial-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .testimonial-stars {
      display: flex;
      gap: 2px;
      margin-bottom: 16px;
    }
    .testimonial-stars svg { width: 18px; height: 18px; fill: var(--yellow); color: var(--yellow); }

    .testimonial-card blockquote {
      font-size: 15px;
      line-height: 1.7;
      color: var(--gray-700);
      margin-bottom: 20px;
      font-style: italic;
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .author-avatar {
      width: 40px; height: 40px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 15px;
      color: var(--white);
    }
    .author-avatar.priya { background: #7c3aed; }
    .author-avatar.james { background: #047857; }
    .author-avatar.laura { background: #b45309; }

    .author-info strong {
      display: block;
      font-size: 14px;
      color: var(--navy);
    }
    .author-info span {
      font-size: 13px;
      color: var(--gray-500);
    }

    /* ===== MOBILE APP PROMO ===== */
    .app-promo {
      padding: 80px 24px;
      background: var(--white);
    }

    .app-promo-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      gap: 60px;
    }

    .app-promo-content { flex: 1; }
    .app-promo-visual {
      flex: 0 0 320px;
      display: flex;
      justify-content: center;
    }

    .phone-mockup {
      width: 240px;
      height: 480px;
      background: var(--navy);
      border-radius: 36px;
      border: 4px solid var(--gray-800);
      position: relative;
      overflow: hidden;
      box-shadow: var(--shadow-xl);
    }
    .phone-mockup::before {
      content: '';
      position: absolute;
      top: 12px;
      left: 50%;
      transform: translateX(-50%);
      width: 60px;
      height: 6px;
      background: var(--gray-700);
      border-radius: 3px;
    }
    .phone-screen {
      margin: 28px 12px 12px;
      height: calc(100% - 40px);
      background: linear-gradient(180deg, var(--navy-light) 0%, var(--navy) 100%);
      border-radius: 24px;
      padding: 24px 16px;
      display: flex;
      flex-direction: column;
      align-items: center;
    }
    .phone-screen .mini-logo {
      font-weight: 800;
      font-size: 18px;
      color: var(--white);
      margin-bottom: 4px;
    }
    .phone-screen .mini-logo span { color: var(--yellow); }
    .phone-screen .mini-bar {
      width: 100%;
      background: rgba(255,255,255,0.15);
      border-radius: var(--radius-sm);
      height: 8px;
      margin-bottom: 10px;
    }
    .phone-screen .mini-card {
      width: 100%;
      background: rgba(255,255,255,0.1);
      border-radius: var(--radius-sm);
      padding: 12px;
      margin-bottom: 8px;
    }
    .phone-screen .mini-card .mini-line {
      height: 6px;
      background: rgba(255,255,255,0.2);
      border-radius: 3px;
      margin-bottom: 6px;
    }
    .phone-screen .mini-card .mini-line:last-child { margin-bottom: 0; width: 60%; }
    .phone-screen .mini-card .mini-line.short { width: 40%; }
    .phone-screen .mini-btn {
      width: 100%;
      padding: 10px;
      background: var(--yellow);
      border-radius: var(--radius-sm);
      color: var(--navy);
      font-weight: 700;
      font-size: 11px;
      text-align: center;
      margin-top: auto;
    }

    .app-promo-content h2 {
      font-size: clamp(28px, 3.5vw, 36px);
      font-weight: 800;
      color: var(--navy);
      margin-bottom: 16px;
      letter-spacing: -0.02em;
    }
    .app-promo-content > p {
      font-size: 17px;
      color: var(--gray-500);
      line-height: 1.6;
      margin-bottom: 32px;
      max-width: 480px;
    }

    .app-features {
      list-style: none;
      margin-bottom: 32px;
    }
    .app-features li {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 8px 0;
      font-size: 15px;
      color: var(--gray-700);
    }
    .app-features li svg { width: 20px; height: 20px; color: var(--teal); flex-shrink: 0; }

    .app-buttons {
      display: flex;
      gap: 12px;
    }
    .store-btn {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 12px 20px;
      background: var(--navy);
      color: var(--white);
      border-radius: var(--radius-md);
      text-decoration: none;
      transition: all var(--transition);
      border: 1px solid transparent;
    }
    .store-btn:hover { background: var(--navy-light); transform: translateY(-1px); }
    .store-btn svg { width: 24px; height: 24px; }
    .store-btn .store-text { text-align: left; }
    .store-btn .store-text small { font-size: 10px; opacity: 0.8; display: block; }
    .store-btn .store-text span { font-size: 14px; font-weight: 600; }

    /* ===== FOOTER ===== */
    .footer {
      padding: 60px 24px 32px;
      background: var(--gray-800);
    }

