  <script>
    // ===== HEADER SCROLL EFFECT =====
    const header = document.getElementById('header');
    window.addEventListener('scroll', () => {
      header.classList.toggle('scrolled', window.scrollY > 10);
    });

    // ===== MOBILE MENU =====
    const hamburgerBtn = document.getElementById('hamburger-btn');
    const mobileDrawer = document.getElementById('mobile-drawer');
    const drawerOverlay = document.getElementById('drawer-overlay');
    const drawerClose = document.getElementById('drawer-close');

    function openDrawer() {
      mobileDrawer.classList.add('open');
      drawerOverlay.classList.add('open');
      document.body.style.overflow = 'hidden';
    }
    function closeDrawer() {
      mobileDrawer.classList.remove('open');
      drawerOverlay.classList.remove('open');
      document.body.style.overflow = '';
    }

    hamburgerBtn.addEventListener('click', openDrawer);
    drawerClose.addEventListener('click', closeDrawer);
    drawerOverlay.addEventListener('click', closeDrawer);

    mobileDrawer.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', closeDrawer);
    });

    // ===== SEARCH AUTOCOMPLETE =====
    const specialtyInput = document.getElementById('specialty-input');
    const dropdown = document.getElementById('autocomplete-dropdown');
    const searchForm = document.getElementById('search-form');

    const suggestions = [
      { text: 'Primary Care', type: 'Specialty' },
      { text: 'Dentist', type: 'Specialty' },
      { text: 'Dermatologist', type: 'Specialty' },
      { text: 'Psychiatrist', type: 'Specialty' },
      { text: 'Eye Doctor', type: 'Specialty' },
      { text: 'Orthopedic Surgeon', type: 'Specialty' },
      { text: 'Back Pain', type: 'Condition' },
      { text: 'Acne', type: 'Condition' },
      { text: 'Anxiety', type: 'Condition' },
      { text: 'Migraine', type: 'Condition' },
      { text: 'Allergies', type: 'Condition' },
      { text: 'Dr. Sarah Chen', type: 'Doctor' },
      { text: 'Dr. Michael Rivera', type: 'Doctor' },
      { text: 'Dr. Emily Patel', type: 'Doctor' },
      { text: 'Dr. James Kim', type: 'Doctor' },
    ];

    function highlightMatch(text, query) {
      if (!query) return text;
      const regex = new RegExp(`(${query.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
      return text.replace(regex, '<mark>$1</mark>');
    }

    function getTypeIcon(type) {
      if (type === 'Specialty') return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M22 12h-4l-3 9L9 3l-3 9H2"/></svg>';
      if (type === 'Condition') return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M12 2a5 5 0 0 1 5 5c0 3-2 5-5 9-3-4-5-6-5-9a5 5 0 0 1 5-5z"/></svg>';
      return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>';
    }

    specialtyInput.addEventListener('input', function() {
      const query = this.value.trim().toLowerCase();
      if (query.length < 1) {
        dropdown.classList.remove('visible');
        return;
      }

      const matches = suggestions.filter(s =>
        s.text.toLowerCase().includes(query)
      ).slice(0, 6);

      if (matches.length === 0) {
        dropdown.classList.remove('visible');
        return;
      }

      dropdown.innerHTML = matches.map(s => `
        <div class="autocomplete-item" data-value="${s.text}">
          ${getTypeIcon(s.type)}
          <span>${highlightMatch(s.text, query)}</span>
          <span class="type">${s.type}</span>
        </div>
      `).join('');

      dropdown.classList.add('visible');

      dropdown.querySelectorAll('.autocomplete-item').forEach(item => {
        item.addEventListener('mousedown', function(e) {
          e.preventDefault();
          specialtyInput.value = this.dataset.value;
          dropdown.classList.remove('visible');
        });
      });
    });

    specialtyInput.addEventListener('blur', () => {
      setTimeout(() => dropdown.classList.remove('visible'), 150);
    });

    specialtyInput.addEventListener('focus', () => {
      if (specialtyInput.value.trim().length >= 1) {
        specialtyInput.dispatchEvent(new Event('input'));
      }
    });

    // ===== SEARCH FORM SUBMIT =====
    searchForm.addEventListener('submit', function(e) {
      e.preventDefault();
      const specialty = specialtyInput.value.trim();
      const location = document.getElementById('location-input').value.trim();
      const insurance = document.getElementById('insurance-select').value;

      if (!specialty && !location) {
        specialtyInput.focus();
        return;
      }

      const params = new URLSearchParams();
      if (specialty) params.set('q', specialty);
      if (location) params.set('loc', location);
      if (insurance) params.set('ins', insurance);

      alert(`Searching for: ${specialty || 'All providers'}${location ? ' near ' + location : ''}${insurance ? ' accepting ' + insurance : ''}`);
    });

    // ===== GEOLOCATION =====
    const geoBtn = document.getElementById('geo-btn');
    const locationInput = document.getElementById('location-input');

    geoBtn.addEventListener('click', function() {
      if (!navigator.geolocation) return;
      this.style.opacity = '0.5';
      navigator.geolocation.getCurrentPosition(
        () => {
          locationInput.value = 'Current Location';
          this.style.opacity = '1';
        },
        () => {
          locationInput.value = 'New York, NY';
          this.style.opacity = '1';
        }
      );
    });

    // ===== SPECIALTY CARD CLICKS =====
    document.querySelectorAll('.specialty-card').forEach(card => {
      card.addEventListener('click', function(e) {
        e.preventDefault();
        const specialty = this.dataset.specialty;
        alert(`Browsing ${specialty} providers in your area`);
      });
    });

    // ===== SCROLL ANIMATIONS =====
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
          observer.unobserve(entry.target);
        }
      });
    }, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });

    document.querySelectorAll('.animate-in').forEach(el => observer.observe(el));
  </script>
